from math import exp

def f(x):
    return 3 - 2 * exp(-x)

def rang(a):
    n = 0
    u = 1
    while u < a:
        u = f(u)
        n = n + 1
    return n

from math import exp

def f(x):
    return (20 * x + 8) * exp(-x / 4)

def solution_equation():
    a = 14
    b = 15
    while b - a > 0.1:
        m = (a + b) / 2
        if f(m) > 8:
            a = m
        else:
            b = m
    return [a, b]
